Section OCHI.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

Definition OCHI_STACK : Z := 144 + AFS_STACK.

Definition ochi_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo shi : Z) (LF : list fframe) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (ex_W H lo sp ff fp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' (P + 288) [C8 (wz 0)]
    /\ fresh_frame H LF 1 ff fp /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
    /\ accessible m' (P + 288) 8
    /\ (exists sh16, rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) [CB 16 sh16]).   (* [comment removed for export] *)

Definition ochi_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo shi : Z) (LF : list fframe),
  rw_cells bsegs m (P + 288) [C8 (wz 0)] ->
  stk bsegs m lo (bv_unsigned sp) -> lo + OCHI_STACK <= bv_unsigned sp -> aceil <= lo ->
  0 < P -> P + 296 <= lo -> P mod 8 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  accessible m (P + 288) 8 -> ex_place H LF (P + 288) 8 ->
  evt bsegs (ochi_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo shi LF m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_ON_CHUNK_HEADER_IMPL) fc None m (seg_rom bsegs)).
