Lemma ochi_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s3x s4x s5x s6x s7x t3' t4' t5' t6' : word)
    (P spa lo shi ff fp : Z) (LF : list fframe) (m mx : mem) (j32 v16 hjunk sh16 : list byte) (bflag : byte),
  rw_cells bsegs mx (bv_unsigned sp + -128) [CB 32 j32; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells bsegs mx (bv_unsigned sp + -144) [CB 16 v16] ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo (bv_unsigned sp + -144) -> mem_inv bsegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  munch (ex_W H lo sp ff fp) m mx -> wmono bsegs m mx ->
  (forall m', munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z mx m' -> wmono bsegs mx m' ->
     rw_cells bsegs m' (P + 288) [C8 (wz 0)] /\ accessible m' (P + 288) 8) ->
  lo + OCHI_STACK <= bv_unsigned sp -> aceil <= lo ->
  evt bsegs (ochi_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo shi LF m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) s3x s4x s5x s6x s7x
             (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3' t4' t5' t6')
        F (Z_to_bv 64 0xba0d4) fc None mx (seg_rom bsegs)).
