Definition APCH_RA_OCHI : Z := 0xd2eb4.

Definition pch_atcall (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a5 a6 a7 s4x s5x t3 t4 t5 t6 (m1 : mem) (c1 : pcore) (pv size eol start : Z) (g : bool) (junk : list byte),
    ms' = MS (mkR (Z_to_bv 64 APCH_RA_OCHI) (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz E) (wz (P + 56))
                  (wz P) a1 a2 a3 (wz E) a5 a6 a7
                  (wz P) (wz IN) s4x s5x (wz (E + 16)) (wz size) (shw (E + 16)) (wz 2147450880) (shw (P + 56)) (shw IN) t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_ON_CHUNK_HEADER_IMPL) fc None m1 (seg_rom bsegs)
    /\ pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs pv
               [C8 (wz start); C8 (wz eol); C8 (shw (P + 76))] [C8 (wz 0); C8 (wz 0); C8 (wz 0)] g junk
    /\ pch_tcore c c1
    /\ p0 + 2 <= eol <= p0 + Z.of_nat (length bs) /\ 0 <= size < 2^64 /\ 0 <= start < 2^64 /\ 0 <= pv < 2^64.

Definition pch_postI (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => pch_post0 ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m ms'
             \/ pch_atcall ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m ms'.

