Ltac pch_finish p' E' c' g' :=
  apply evt_done; left; unfold pch_post0;
  do 16 eexists; exists p', E', c', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try assumption; try lia.

